package de.ostms.lc.user.api;
import de.ostms.lc.audit.service.AuditService;import de.ostms.lc.user.service.*;import jakarta.servlet.http.*;import org.springframework.http.*;import org.springframework.security.authentication.*;import org.springframework.security.core.*;import org.springframework.security.core.context.*;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.security.web.authentication.logout.SecurityContextLogoutHandler;import org.springframework.security.web.context.*;import org.springframework.security.web.csrf.CsrfToken;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private TenantLoginService tenantLogin;private static final String PENDING_TENANT="TOTP_PENDING_TENANT";
 @org.springframework.beans.factory.annotation.Autowired public AuthController(AuthenticationManager manager,UserService users,AppUserDetailsService details,TotpService totp,AuditService audit,LoginAttemptLimiter limiter,TenantLoginService tenantLogin){this(manager,users,details,totp,audit,limiter);this.tenantLogin=tenantLogin;}
 private static final String TOTP_PENDING_LOGIN="TOTP_PENDING_LOGIN",TOTP_PENDING_SECRET="TOTP_PENDING_SECRET";private final AuthenticationManager manager;private final UserService users;private final AppUserDetailsService details;private final TotpService totp;private final AuditService audit;private final LoginAttemptLimiter limiter;private static final String PENDING_AT="TOTP_PENDING_AT";private static final long PENDING_MAX_MS=300_000;private final SecurityContextRepository contexts=new HttpSessionSecurityContextRepository();
 public AuthController(AuthenticationManager manager,UserService users,AppUserDetailsService details,TotpService totp,AuditService audit,LoginAttemptLimiter limiter){this.manager=manager;this.users=users;this.details=details;this.totp=totp;this.audit=audit;this.limiter=limiter;}public record LoginRequest(String username,String password,String tenantCode){public LoginRequest(String username,String password){this(username,password,null);}}public record TotpCodeRequest(String code){}public record TotpDisableRequest(String password,String code){}public record PasswordChangeRequest(String currentPassword,String newPassword){}
 @PostMapping("/login") public ResponseEntity<?> login(@RequestBody LoginRequest body,HttpServletRequest request,HttpServletResponse response){try(var home=de.ostms.lc.tenant.domain.TenantContext.open(de.ostms.lc.tenant.domain.Tenant.DEFAULT_ID)){return loginInternal(body,request,response);}}
 private ResponseEntity<?> loginInternal(LoginRequest body,HttpServletRequest request,HttpServletResponse response){if(!limiter.allow("password",body.username(),request.getRemoteAddr()))return throttled();try{HttpSession old=request.getSession(false);if(old!=null)old.invalidate();SecurityContextHolder.clearContext();request.getSession(true);UUID target=de.ostms.lc.tenant.domain.Tenant.DEFAULT_ID;String stamp;Authentication auth;if(tenantLogin!=null){var verified=tenantLogin.verify(body.username(),body.password(),body.tenantCode());target=verified.tenantId();stamp=CredentialStamp.of(verified.user().getPassword());auth=UsernamePasswordAuthenticationToken.authenticated(verified.user().getUsername(),null,verified.user().getAuthorities());}else{if(body.tenantCode()!=null&&!body.tenantCode().isBlank())throw new BadCredentialsException("Explicit tenant authentication is unavailable.");stamp=CredentialStamp.of(details.loadUserByUsername(body.username()).getPassword());auth=manager.authenticate(UsernamePasswordAuthenticationToken.unauthenticated(body.username(),body.password()));}if(totp.enabled(auth.getName())||admin(auth)){request.changeSessionId();request.getSession().setAttribute(PENDING_AT,System.currentTimeMillis());request.getSession(true).setAttribute(TOTP_PENDING_LOGIN,auth.getName());request.getSession().setAttribute("TOTP_PENDING_STAMP",stamp);request.getSession().setAttribute(PENDING_TENANT,target);loginAudit(target,auth.getName(),"LOGIN_TOTP_REQUIRED","SESSION",null,"Passwort geprüft, zweiter Faktor angefordert",true,request.getRemoteAddr());if(!totp.enabled(auth.getName())){var setup=totp.setup(auth.getName());request.getSession().setAttribute(TOTP_PENDING_SECRET,setup.secret());return ResponseEntity.ok(Map.of("requiresTotpSetup",true,"qrCodeDataUrl",setup.qrCodeDataUrl(),"secret",setup.secret()));}return ResponseEntity.ok(Map.of("requiresTotp",true));}authenticate(auth,request,response,stamp,target,false);loginAudit(target,auth.getName(),"LOGIN","SESSION",null,"Anmeldung erfolgreich",true,request.getRemoteAddr());return ResponseEntity.ok(Map.of("username",auth.getName(),"requiresTotp",false));}catch(org.springframework.security.core.AuthenticationException ex){audit.record(body.username(),"LOGIN","SESSION",null,"Anmeldung fehlgeschlagen",false,request.getRemoteAddr());return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error","Benutzername oder Passwort ist falsch."));}}
 @PostMapping("/login/totp") public ResponseEntity<?> loginTotp(@RequestBody TotpCodeRequest body,HttpServletRequest request,HttpServletResponse response){try(var home=de.ostms.lc.tenant.domain.TenantContext.open(de.ostms.lc.tenant.domain.Tenant.DEFAULT_ID)){return loginTotpInternal(body,request,response);}}
 private ResponseEntity<?> loginTotpInternal(TotpCodeRequest body,HttpServletRequest request,HttpServletResponse response){HttpSession session=request.getSession(false);String username=session==null?null:(String)session.getAttribute(TOTP_PENDING_LOGIN);if(username!=null){Object started=session.getAttribute(PENDING_AT);if(!(started instanceof Long)||System.currentTimeMillis()-(Long)started>=PENDING_MAX_MS){session.invalidate();username=null;}}if(username==null)return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error","Die Anmeldung ist abgelaufen. Bitte erneut anmelden."));if(!limiter.allow("totp",username,request.getRemoteAddr()))return throttled();Object pendingTenant=session.getAttribute(PENDING_TENANT);UUID target=pendingTenant instanceof UUID id?id:de.ostms.lc.tenant.domain.Tenant.DEFAULT_ID;if((tenantLogin!=null||pendingTenant!=null)&&!(pendingTenant instanceof UUID)){session.invalidate();return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error","Please sign in again."));}UserDetails user;try{user=tenantLogin==null?details.loadUserByUsername(username):details.loadForTenant(username,target);}catch(org.springframework.security.core.AuthenticationException ex){session.invalidate();return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error","Bitte erneut anmelden."));}String stamp=(String)session.getAttribute("TOTP_PENDING_STAMP");if(!user.isEnabled()||!CredentialStamp.of(user.getPassword()).equals(stamp)){session.invalidate();return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error","Bitte erneut anmelden."));}List<String> recovery=null;if(session.getAttribute(TOTP_PENDING_SECRET) instanceof String secret&&!totp.enabled(username)){try{recovery=totp.enable(username,secret,body.code());loginAudit(target,username,"TOTP_ENABLED","USER",username,"Pflicht-2FA bei Anmeldung eingerichtet",true,request.getRemoteAddr());}catch(IllegalArgumentException ex){loginAudit(target,username,"LOGIN_TOTP_FAILED","SESSION",null,"Einrichtungscode abgelehnt",false,request.getRemoteAddr());return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error","Der Sicherheitscode ist nicht gültig."));}}else if(!totp.verifyLogin(username,body.code())){loginAudit(target,username,"LOGIN_TOTP_FAILED","SESSION",null,"Zweiter Faktor abgelehnt",false,request.getRemoteAddr());return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error","TOTP- oder Notfallcode ist nicht gültig."));}Authentication auth=UsernamePasswordAuthenticationToken.authenticated(user.getUsername(),null,user.getAuthorities());authenticate(auth,request,response,stamp,target,true);session.removeAttribute(TOTP_PENDING_LOGIN);loginAudit(target,username,"LOGIN","SESSION",null,"Anmeldung mit zweitem Faktor erfolgreich",true,request.getRemoteAddr());return ResponseEntity.ok(recovery==null?Map.of("username",username):Map.of("username",username,"recoveryCodes",recovery));}
 @GetMapping("/me") public Map<String,Object> me(Authentication auth,CsrfToken csrf){String role=auth.getAuthorities().stream().map(GrantedAuthority::getAuthority).filter(x->x.startsWith("ROLE_")).map(x->x.substring(5)).findFirst().orElse("USER");List<String> permissions=auth.getAuthorities().stream().map(GrantedAuthority::getAuthority).filter(x->x.startsWith("PERM_")).map(x->x.substring(5)).toList();return Map.of("username",auth.getName(),"role",role,"permissions",permissions,"csrfToken",csrf.getToken(),"totpEnabled",totp.enabled(auth.getName()));}
 @PostMapping("/totp/setup") public TotpService.Setup setupTotp(Authentication auth,HttpServletRequest request){TotpService.Setup setup=totp.setup(auth.getName());request.getSession(true).setAttribute(TOTP_PENDING_SECRET,setup.secret());audit.record(auth,"TOTP_SETUP_STARTED","USER",auth.getName(),"2FA-Einrichtung begonnen");return setup;}
 @PostMapping("/totp/enable") public Map<String,List<String>> enableTotp(@RequestBody TotpCodeRequest body,Authentication auth,HttpServletRequest request){String secret=(String)request.getSession(true).getAttribute(TOTP_PENDING_SECRET);if(secret==null)throw new IllegalStateException("Bitte die 2FA-Einrichtung erneut starten.");List<String> recovery=totp.enable(auth.getName(),secret,body.code());request.getSession().removeAttribute(TOTP_PENDING_SECRET);request.getSession().setAttribute(de.ostms.lc.config.CredentialSessionFilter.TOTP_VERIFIED,true);audit.record(auth,"TOTP_ENABLED","USER",auth.getName(),"Zwei-Faktor-Anmeldung aktiviert");return Map.of("recoveryCodes",recovery);}
 @PostMapping("/totp/disable") public ResponseEntity<Void> disableTotp(@RequestBody TotpDisableRequest body,Authentication auth){totp.disable(auth.getName(),body.password(),body.code());audit.record(auth,"TOTP_DISABLED","USER",auth.getName(),"Zwei-Faktor-Anmeldung deaktiviert");return ResponseEntity.noContent().build();}
 @PostMapping("/password") public ResponseEntity<Void> changePassword(@RequestBody PasswordChangeRequest body,Authentication auth){users.changePassword(auth.getName(),body.currentPassword(),body.newPassword());audit.record(auth,"PASSWORD_CHANGED","USER",auth.getName(),"Eigenes Passwort geändert");return ResponseEntity.noContent().build();}
 @PostMapping("/logout") public ResponseEntity<Void> logout(HttpServletRequest request,HttpServletResponse response,Authentication auth){audit.record(auth,"LOGOUT","SESSION",null,"Abmeldung");new SecurityContextLogoutHandler().logout(request,response,auth);return ResponseEntity.noContent().build();}
 private void loginAudit(UUID tenant,String username,String action,String type,Object id,String message,boolean success,String ip){try(var scope=de.ostms.lc.tenant.domain.TenantContext.open(tenant)){audit.record(username,action,type,id,message,success,ip);}}
 private boolean admin(Authentication auth){return auth.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_ADMIN"));}
 private ResponseEntity<?> throttled(){return ResponseEntity.status(429).header("Retry-After","300").body(Map.of("error","Zu viele Anmeldeversuche. Bitte in fünf Minuten erneut versuchen."));}
private void authenticate(Authentication auth,HttpServletRequest request,HttpServletResponse response,String stamp,UUID target,boolean verifiedTotp){limiter.succeeded("password",auth.getName());limiter.succeeded("totp",auth.getName());request.changeSessionId();request.getSession().removeAttribute(TOTP_PENDING_SECRET);request.getSession().removeAttribute(PENDING_AT);request.getSession().removeAttribute(TOTP_PENDING_LOGIN);request.getSession().removeAttribute(PENDING_TENANT);request.getSession().removeAttribute("TOTP_PENDING_STAMP");request.getSession().setAttribute(de.ostms.lc.config.CredentialSessionFilter.TOTP_VERIFIED,verifiedTotp);request.getSession().setAttribute(de.ostms.lc.config.CredentialSessionFilter.TENANT,target);request.getSession().setAttribute(de.ostms.lc.config.CredentialSessionFilter.AUTHENTICATED_AT,System.currentTimeMillis());request.getSession().setAttribute(de.ostms.lc.config.CredentialSessionFilter.STAMP,stamp);request.getSession().setAttribute(de.ostms.lc.config.CredentialSessionFilter.AUTHORIZATION_STAMP,AuthorizationStamp.of(auth.getAuthorities()));SecurityContext context=SecurityContextHolder.createEmptyContext();context.setAuthentication(auth);SecurityContextHolder.setContext(context);contexts.saveContext(context,request,response);}
}
